/**
 * A product's render manifest. In production these files come from the 3D/CAD
 * render pipeline (Blender/KeyShot passes). For the demo they are generated by
 * scripts/generate-demo-layers.ts.
 *
 * assets/products/{style}/manifest.json
 * assets/products/{style}/{view}/metal-{METAL}.png      ring body per metal
 * assets/products/{style}/{view}/setting-{METAL}-{shape}.png  stone seat per metal
 * assets/stones/{shape}/{STONE}.png                     stone images
 */
export interface SlotPlacement {
  x: number; // centre
  y: number;
  w: number;
  h: number;
  rotate?: number; // degrees
}

export interface EngravingArea {
  /** Text follows an ellipse arc: centre, radii, from/to angle in degrees */
  cx: number;
  cy: number;
  rx: number;
  ry: number;
  from: number;
  to: number;
  fontSize: number;
  /** Lower the opacity for text on the inside of the band */
  opacity?: number;
}

export interface Point {
  x: number;
  y: number;
}

/**
 * Name necklace drawn procedurally (try-on prototype). Coordinates are in the
 * view's pixel space. neckLeft/neckRight are where the chain disappears behind
 * the neck - the try-on maps these onto the customer's neck.
 */
export interface NameplateSpec {
  textKey: string; // engraving key holding the name, e.g. "e1"
  neckLeft: Point;
  neckRight: Point;
  plateCenter: Point;
  maxPlateWidth: number;
  fontSize: number;
  chainWidth?: number;
  /** APPROXIMATE millimetres per pixel (demo geometry, not measured from CAD). */
  mmPerPx: number;
}

export interface ViewManifest {
  width: number;
  height: number;
  /** CSS colour, or "transparent" for an alpha background (try-on assets). */
  background: string;
  /** When set, this view is a procedurally drawn name necklace instead of layers. */
  nameplate?: NameplateSpec;
  /** Fixed slots (s1, s2...) */
  slots?: Record<string, SlotPlacement>;
  /** Stone-count designs: placements per count, e.g. { "5": { s1: ..., s5: ... } } */
  slotLayouts?: Record<string, Record<string, SlotPlacement>>;
  stoneShape: string;
  engravings: Record<string, EngravingArea>;
}

export interface ProductManifest {
  styleCode: string;
  defaultView: string;
  views: Record<string, ViewManifest>;
}
